@import url('https://fonts.googleapis.com/css2?family=Libre+Franklin:wght@300;400;500;600;700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&display=swap');
/* GENERATED by @substrate/tokens/build.mjs — DO NOT EDIT.
 * Source of truth: packages/tokens/src/*.tokens.json (DTCG).
 * Tier 1: primitives (@theme) → Tier 2: semantic contract (:root / skins)
 * → Tier 3: utility bridge (@theme inline). Style ONLY with semantic utilities. */

@custom-variant dark (&:where(.dark, .dark *, [data-theme='dark'], [data-theme='dark'] *));

/* ── BASE — default border color ─────────────────────────────────────────── */
/* Tailwind v4 dropped v3's `border-color: gray-200` preflight; a bare
 * `border` / `border-b` now paints in `currentColor`, i.e. near-black ink.
 * Every unqualified border in the system silently rendered as a hard rule.
 * Re-point the default at the semantic border token so `border-b` means the
 * hairline it reads as, and a skin can still move it. */
@layer base {
  *,
  ::before,
  ::after,
  ::backdrop {
    border-color: var(--border);
  }
}

/* ── TIER 1 — primitives ─────────────────────────────────────────────────── */
/* `static` is required, not stylistic: plain @theme tree-shakes any custom
 * property no utility or semantic token references, so unreferenced ramp steps
 * (ember-200, signal-700, …) silently resolve to transparent wherever they're
 * read through var() — e.g. the foundations ramp specimens. A token package
 * must emit its whole palette. */
@theme static {
  --font-sans: 'Benton Sans', BentonSans, 'Libre Franklin', system-ui, sans-serif;
  --font-display: 'Benton Sans', BentonSans, 'Libre Franklin', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;


  --color-neutral-0: #FFFFFF;
  --color-neutral-50: #F9F9F9;
  --color-neutral-100: #F2F2F2;
  --color-neutral-200: #E3E3E3;
  --color-neutral-300: #CECECE;
  --color-neutral-400: #ABABAB;
  --color-neutral-500: #8A8A8A;
  --color-neutral-600: #6D6D6D;
  --color-neutral-700: #515151;
  --color-neutral-800: #373737;
  --color-neutral-900: #1F1F1F;
  --color-neutral-950: #0A0A0A;

  --color-signal-50: #F6FAFF;
  --color-signal-100: #EBF2FE;
  --color-signal-200: #D4E5FD;
  --color-signal-300: #B2D0FB;
  --color-signal-400: #78ADF9;
  --color-signal-500: #3687F7;
  --color-signal-600: #2169CC;
